const test=require('node:test');
const assert=require('node:assert/strict');
const app=require('../lib/query-presence.cjs');
test('name-only queries and exact value matches across duplicate keys',()=>{
  const params=new URLSearchParams('tag=north&tag=south&empty=&=blank&mode=0');
  const before=[...params].map(pair=>[...pair]);
  for(const [name,value,expected] of [
    ['tag',undefined,true],['missing',undefined,false],
    ['tag','north',true],['tag','south',true],['tag','west',false],
    ['tag','',false],['empty','',true],['empty',undefined,true],
    ['missing','',false],['','blank',true],['',undefined,true],
    ['mode','0',true],['tag','North',false]
  ]) assert.equal(app.hasFilter(params,name,value),expected);
  assert.deepEqual([...params],before);
  assert.equal(app.hasFilter(new URLSearchParams(),'tag'),false);
});

